import base64, os

HTML_B64 = ""

CSS_B64 = ""

def escrever(caminho, b64):
    os.makedirs(os.path.dirname(caminho), exist_ok=True)
    with open(caminho, "w", encoding="utf-8", newline="\n") as f:
        f.write(base64.b64decode(b64).decode("utf-8"))
    print(f"[OK] {caminho}")

escrever("paginas/performance-semanal.html", HTML_B64)
escrever("paginas/performance-semanal.css", CSS_B64)
print("\nPronto. Recarregue a pagina no navegador.")